      "Domänenzauber: Stufe 1 – Magie entdecken, Magisches Geschoss · Stufe 3 – Magische Waffe, Nystuls magische Aura · Stufe 5 – Magie bannen, Schutzkreis · Stufe 7 – Arkanes Auge, Leomunds geheime Truhe · Stufe 9 – Planare Bindung, Kreis der Teleportation."
