      "Ab Stufe 5 wird eine solche Kreatur verbannt (ohne Konzentration), falls sie sich nicht auf ihrer Heimatebene befindet und ihr HG unter der stufenabhängigen Schwelle liegt (Stufe 5 → HG ½, Stufe 8 → HG 1, Stufe 11 → HG 2, Stufe 14 → HG 3, Stufe 17 → HG 4)."
