      "Objekt lesen: Halte einen Gegenstand und erfahre Visionen seiner früheren Besitzer. Gebiet lesen: Erfahre Visionen von Ereignissen in einem 15-m-Würfel um dich herum aus den vergangenen Tagen (Anzahl = Weisheitsmodifikator). Pro Minute Meditation ein wichtiges Ereignis, beginnend mit dem jüngsten."
